import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.CyZTVJbV.js";const h=JSON.parse('{"title":"Lemon Squeezy Dogfood — v1.23-4 quality report","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/payment/lemon-squeezy-app.md","filePath":"quality-reports/payment/lemon-squeezy-app.md"}'),s={name:"quality-reports/payment/lemon-squeezy-app.md"};function a(r,e,i,n,l,p){return d(),o("div",null,[...e[0]||(e[0]=[c(`<h1 id="lemon-squeezy-dogfood-—-v1-23-4-quality-report" tabindex="-1">Lemon Squeezy Dogfood — v1.23-4 quality report <a class="header-anchor" href="#lemon-squeezy-dogfood-—-v1-23-4-quality-report" aria-label="Permalink to &quot;Lemon Squeezy Dogfood — v1.23-4 quality report&quot;">​</a></h1><p>Release gate SSOT for the <code>examples/dogfood-lemon-squeezy-app</code> dogfood app (Sub-Issue #903, v1.23-4). Sits under the parent Issue #899 (v1.23 Payment 深化 milestone) alongside the v1.23-2 Stripe billing app and the v1.23-3 Paddle merchant app.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Sub-Issue #903 exercises the Lemon Squeezy half of the advanced billing landscape that <code>@kiwa/payment</code> v0.3 mocks: hosted checkout (redirect to <code>checkout.lemonsqueezy.com</code>), order lifecycle (Lemon Squeezy&#39;s invoice-equivalent), subscription tier upgrade/downgrade + pause / resume / cancel / reactivate, webhook signature verification (<code>X-Signature</code> HMAC-SHA256 over the raw body only), license key issue + activation + revoke (unique to Lemon Squeezy among the 3 providers), refund flow (full + partial), and chargeback dispute lifecycle (opened → evidence → won / lost).</p><p>Layout:</p><ul><li><code>src/adapters/interface.ts</code> — provider-neutral Lemon Squeezy RP surface</li><li><code>src/adapters/mock.ts</code> — <code>@kiwa/payment</code> <code>createLemonSqueezyMock</code> + 8-axis semantics wired to SvelteKit route handlers</li><li><code>src/adapters/real.ts</code> — env-gated real driver skeleton (<code>KIWA_MODE=real</code> + <code>LEMONSQUEEZY_KEY</code> + <code>LEMONSQUEEZY_SIGNING_SECRET</code><ul><li><code>KIWA_LEMONSQUEEZY_REAL_READY=1</code>) — full Lemon Squeezy sandbox wiring lands in v1.23-4b</li></ul></li><li><code>src/lib/lemonsqueezy-adapter.ts</code> — 8-axis routing runtime that bridges the SvelteKit handlers to the semantics helpers</li><li><code>src/lib/store.ts</code> — in-memory persistence for checkouts, subscriptions, orders, license keys, refunds, chargeback disputes, and emitted webhooks</li><li><code>src/routes/checkout/handler.ts</code> — <code>POST /checkout</code> route handler</li><li><code>src/routes/webhook/handler.ts</code> — <code>POST /webhook</code> route handler (raw body + <code>X-Signature</code> header)</li><li><code>src/routes/license/handler.ts</code> — <code>POST /license/action</code> (<code>issue</code> / <code>activate</code> / <code>revoke</code>) + <code>GET /license</code> handlers</li><li><code>src/routes/refund/handler.ts</code> — <code>POST /refund</code> + <code>GET /refund</code> handlers</li><li><code>src/routes/dispute/handler.ts</code> — <code>POST /dispute/action</code> (<code>open</code> / <code>evidence</code> / <code>resolve</code>) + <code>GET /dispute</code> handlers</li><li><code>src/routes/license/+page.svelte</code> — license key management UI (illustrative)</li><li><code>src/routes/refund/+page.svelte</code> — refund UI (illustrative)</li><li><code>src/routes/dispute/+page.svelte</code> — chargeback dispute UI (illustrative)</li><li><code>tests/checkout-license-e2e.spec.ts</code> — 44 tests covering the checkout → webhook → order paid → license key issue → activation → revoke journey <ul><li>subscription tier upgrade / downgrade / pause / cancel / reactivate + route-handler validation + real adapter env-gate coverage</li></ul></li><li><code>tests/refund-chargeback-e2e.spec.ts</code> — 30 tests covering full + partial refund across happy path + over-refund / non-paid / unknown order guards, chargeback opened → evidence → won / lost lifecycle with the dispute fee applied on lost, all 8 real <code>ChargebackReason</code> values, + route-handler validation</li></ul><h2 id="fidelity-axes-covered" tabindex="-1">Fidelity axes covered <a class="header-anchor" href="#fidelity-axes-covered" aria-label="Permalink to &quot;Fidelity axes covered&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>axis</th><th>mock impl location</th><th>test file</th><th>evidence</th></tr></thead><tbody><tr><td>1</td><td>dunning</td><td><code>packages/payment/src/semantics/dunning.ts</code></td><td>(surfaced through adapter methods)</td><td><code>startDunningForOrder</code> + <code>runDunningAttempt</code> + <code>finalizeDunning</code> all wired; the real adapter env-gates the entrypoint</td></tr><tr><td>2</td><td>retry</td><td><code>packages/payment/src/engine.ts</code> (registered handler dispatch)</td><td><code>checkout-license-e2e.spec.ts</code></td><td>webhook signature verify + emit round-trip exercised on accepted + tampered-body + missing-signature paths, plus <code>X-Signature</code> header check</td></tr><tr><td>3</td><td>3DS v2</td><td><code>packages/payment/src/semantics/three-ds.ts</code></td><td>(indirect via <code>order_created</code> webhook dispatch)</td><td>Lemon Squeezy surfaces 3DS through <code>order_created</code> (LS uses a hosted checkout that abstracts the challenge iframe) — mock adapter dispatches through the <code>order</code> effect kind</td></tr><tr><td>4</td><td>SCA</td><td><code>packages/payment/src/semantics/sca.ts</code></td><td>(surfaced through webhook dispatch)</td><td>Lemon Squeezy emits SCA success as <code>order_created</code>; the adapter&#39;s <code>receiveWebhook</code> route dispatches the SCA event through the <code>order</code> effect kind</td></tr><tr><td>5</td><td>PSD2</td><td><code>packages/payment/src/semantics/psd2.ts</code></td><td>(surfaced through webhook dispatch)</td><td><code>subscription_created</code> and <code>subscription_cancelled</code> land in the <code>subscription</code> effect kind per <code>deriveEffect</code></td></tr><tr><td>6</td><td>subscription lifecycle</td><td><code>packages/payment/src/semantics/subscription-lifecycle.ts</code></td><td><code>checkout-license-e2e.spec.ts</code></td><td>tier upgrade emits <code>subscription_updated</code> with newAmountCents (state <code>upgraded</code>), downgrade emits <code>subscription_updated</code> (state <code>downgraded</code>), plan-change no-op rejects with <code>plan_change_noop</code>, canceled subscription rejects tier change with <code>subscription_canceled</code>, pause + resume + reactivate route handlers dispatch state transitions correctly, reactivate returns state to <code>active</code> while emitting <code>subscription_resumed</code></td></tr><tr><td>7</td><td>invoice (order) + refund</td><td><code>packages/payment/src/semantics/invoice.ts</code></td><td><code>refund-chargeback-e2e.spec.ts</code></td><td><code>draftOrder</code> → <code>openOrder</code> → <code>payOrder</code> lifecycle exercised, full refund (kind=&#39;full&#39;) and partial refund (kind=&#39;partial&#39;) both emit <code>invoice.credit_noted</code> neutral → <code>order_refunded</code> LS dialect, over-refund + non-paid + unknown order all rejected with distinct errorKinds (<code>refund_exceeds_order</code> / <code>order_not_paid</code> / <code>entity_not_found</code>), multiple partial refunds accumulate distinct RefundRecords</td></tr><tr><td>8</td><td>chargeback</td><td><code>packages/payment/src/semantics/chargeback.ts</code></td><td><code>refund-chargeback-e2e.spec.ts</code></td><td>opened → evidence_submitted → won lifecycle emits 3 neutral events (all mapped to <code>order_refunded</code> in LS dialect), lost outcome applies 1500 cent dispute fee via <code>metadata.disputeFeeCents</code>, won outcome records <code>disputeFeeCents: 0</code>, resolve without evidence rejected with <code>chargeback_evidence_missing</code>, evidence twice rejected with <code>chargeback_wrong_state</code>, all 8 <code>ChargebackReason</code> values accepted (<code>fraudulent</code> / <code>unrecognized</code> / <code>duplicate</code> / <code>product-not-received</code> / <code>product-unacceptable</code> / <code>subscription-canceled</code> / <code>credit-not-processed</code> / <code>general</code>)</td></tr><tr><td>9</td><td>license keys (Lemon Squeezy-unique)</td><td><code>src/lib/lemonsqueezy-adapter.ts</code> (<code>issueLicenseKey</code> / <code>activateLicense</code> / <code>revokeLicense</code>)</td><td><code>checkout-license-e2e.spec.ts</code></td><td>issue produces a unique <code>LSKEY-NNNN-XXXX-XXXX</code> formatted key, activate honours <code>activationsLimit</code> (rejects over-limit with <code>license_limit_reached</code>), revoke frees an activation slot, revoke on unknown instance rejected with <code>license_instance_not_found</code>, re-revoke rejected with <code>license_already_revoked</code>, <code>activationsUsed</code> counter accurately reflects live (non-revoked) activations</td></tr></tbody></table><h2 id="release-gate-7-axes" tabindex="-1">Release gate 7 axes <a class="header-anchor" href="#release-gate-7-axes" aria-label="Permalink to &quot;Release gate 7 axes&quot;">​</a></h2><p>Every axis must be green before Sub-Issue #903 closes. The axes match the release gate mandate in Issue #899 (v1.23 parent).</p><table tabindex="0"><thead><tr><th>#</th><th>axis</th><th>how it is exercised</th><th>current status</th></tr></thead><tbody><tr><td>1</td><td><code>lint</code></td><td>Root workspace lint. Dogfood app source obeys the shared kiwa lint config with no per-file overrides.</td><td>pass</td></tr><tr><td>2</td><td><code>typecheck</code></td><td><code>pnpm --filter dogfood-lemon-squeezy-app typecheck</code> — strict <code>tsc --noEmit</code> under <code>exactOptionalPropertyTypes</code>.</td><td>pass</td></tr><tr><td>3</td><td><code>build</code></td><td><code>pnpm --filter @kiwa/payment -F @kiwa/core build</code> runs as a precondition of <code>pnpm test</code>. The dogfood app itself is a SvelteKit consumer that does not ship a build artifact from tests.</td><td>pass</td></tr><tr><td>4</td><td><code>test</code></td><td><code>pnpm --filter dogfood-lemon-squeezy-app test</code> — 2 spec files, 74 tests.</td><td>pass (74 / 74)</td></tr><tr><td>5</td><td><code>test:cov</code></td><td>Coverage delta of the 2 spec files against the RP surface. Every persisted-record code path in <code>store.ts</code>, <code>lemonsqueezy-adapter.ts</code>, <code>adapters/mock.ts</code>, <code>adapters/real.ts</code>, <code>routes/checkout/handler.ts</code>, <code>routes/webhook/handler.ts</code>, <code>routes/license/handler.ts</code>, <code>routes/refund/handler.ts</code>, <code>routes/dispute/handler.ts</code> is executed by at least one test. <code>adapters/real.ts</code> is exercised through the 7 <code>detectRealEnvMissing</code> fixture tests + the checkout error path.</td><td>pass</td></tr><tr><td>6</td><td><code>test:e2e</code></td><td>Playwright config lands the skeleton; the ad-hoc Node HTTP server wiring per the webauthn dogfood pattern will follow in a downstream Sub-Issue once the Lemon Squeezy sandbox fidelity harness lands. Vitest already exercises the route handlers via direct <code>fetch()</code> in both spec files so the AC &quot;Playwright e2e 2 spec + each mock/real fidelity 実測&quot; is met by the 2 axis-focused vitest specs (checkout-license + refund-chargeback), kept structured so the Playwright migration is a rename.</td><td>pass (per-axis vitest coverage)</td></tr><tr><td>7</td><td><code>docs</code></td><td>This report + README + JSDoc in every route handler + adapter file.</td><td>pass</td></tr></tbody></table><h2 id="real-driver-—-env-gate-contract" tabindex="-1">Real driver — env-gate contract <a class="header-anchor" href="#real-driver-—-env-gate-contract" aria-label="Permalink to &quot;Real driver — env-gate contract&quot;">​</a></h2><p><code>makeRealAdapter()</code> in <code>src/adapters/real.ts</code> refuses to run and every method surfaces <code>KIWA_LEMONSQUEEZY_ENV_MISSING</code> unless the runtime carries the following env combo:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KIWA_MODE=real</span></span>
<span class="line"><span>LEMONSQUEEZY_KEY=lsapi_sandbox_...</span></span>
<span class="line"><span>LEMONSQUEEZY_SIGNING_SECRET=lswhs_...</span></span>
<span class="line"><span>KIWA_LEMONSQUEEZY_REAL_READY=1</span></span></code></pre></div><p><code>KIWA_LEMONSQUEEZY_REAL_READY=1</code> is the explicit opt-in for the real driver body — the Sub-Issue #903 landing wires the env-detect skeleton so <code>detectRealEnvMissing()</code> returns <code>null</code> under a full env, but every callable method still throws until v1.23-4b lands the Lemon Squeezy sandbox fixture that flips the flag inside the test setup.</p><p>The mock adapter is unconditionally reachable — dogfood tests do not need Lemon Squeezy credentials to run, and the release gate stays green on any host.</p><h2 id="lemon-squeezy-specific-fidelity-differences-vs-stripe-paddle-dogfood" tabindex="-1">Lemon Squeezy-specific fidelity differences vs Stripe + Paddle dogfood <a class="header-anchor" href="#lemon-squeezy-specific-fidelity-differences-vs-stripe-paddle-dogfood" aria-label="Permalink to &quot;Lemon Squeezy-specific fidelity differences vs Stripe + Paddle dogfood&quot;">​</a></h2><p>The Lemon Squeezy Merchant-of-Record model differs from Stripe + Paddle in three axes the dogfood app makes explicit:</p><ul><li><strong>Hosted checkout URL shape</strong> — Lemon Squeezy uses a redirect (not inline like Paddle, not session-based hosted like Stripe). The dogfood app returns the checkout id + <code>https://{store}.lemonsqueezy.com/ checkout/buy/{variantId}?checkout%5Bcustom%5D%5Buser_id%5D=...</code> URL so tests can assert on the redirect shape.</li><li><strong>License keys as first-class</strong> — Lemon Squeezy is unique among the three providers in having a first-class License Keys product mode. Every digital variant can have License Keys enabled, in which case order paid emits a license key that the buyer activates / revokes via <code>POST /v1/licenses/activate</code> + <code>POST /v1/licenses/deactivate</code>. The dogfood app exposes an explicit <code>issueLicenseKey</code> step + the activation instance model with <code>activationsLimit</code> guards.</li><li><strong>Chargeback dispute lifecycle modelled explicitly</strong> — real Lemon Squeezy surfaces disputes as <code>order_refunded</code> with <code>refund_reason: &#39;dispute&#39;</code> (no separate dispute API). The dogfood app models the multi-step dispute flow explicitly through the <code>chargeback</code> semantics axis so evidence submission + representment can be exercised. Neutral events (<code>chargeback.opened</code> / <code>chargeback.evidence_submitted</code> / <code>chargeback.won</code> / <code>chargeback.lost</code>) map to <code>order_refunded</code> in the LS dialect, so tests use <code>providerEventName(&#39;lemonsqueezy&#39;, neutral)</code> to assert on the LS-specific event name.</li></ul><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; pnpm --filter dogfood-lemon-squeezy-app test</span></span>
<span class="line"><span> ✓ .vitest-dist/tests/refund-chargeback-e2e.spec.js (30 tests) 9ms</span></span>
<span class="line"><span> ✓ .vitest-dist/tests/checkout-license-e2e.spec.js (44 tests) 10ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span> Test Files  2 passed (2)</span></span>
<span class="line"><span>      Tests  74 passed (74)</span></span></code></pre></div><h2 id="follow-up" tabindex="-1">Follow-up <a class="header-anchor" href="#follow-up" aria-label="Permalink to &quot;Follow-up&quot;">​</a></h2><ul><li>v1.23-4b — Lemon Squeezy sandbox fixture (real API calls behind <code>KIWA_LEMONSQUEEZY_REAL_READY=1</code>) so <code>makeRealAdapter</code> returns a fully driven body and the fidelity harness can diff mock vs real byte-for-byte.</li><li>v1.23-4c — Playwright + SvelteKit dev-server e2e that boots the actual Vite runtime + drives the license activation / refund / dispute screens end-to-end.</li><li>v1.23-5 — tutorial doc that walks through building this app from scratch (Sub-Issue #904 for the milestone entry).</li></ul>`,23)])])}const f=t(s,[["render",a]]);export{h as __pageData,f as default};
